use states::{y_minus,y_plus}; use phase_fault::shifted;
use std::quantum::init0; use std::observe::measure_z;
unitary fn use_op[static U:Op<Bit>](q:Q<Bit>)->Q<Bit> requires Apply(U){U(q)}
observe fn main()->Bit{measure_z(use_op[y_minus](init0()))}

